// sqliteDriver is the name modernc.org/sqlite registers under.
const sqliteDriver = "sqlite"

// Store owns the single *sql.DB handle for the process. All other packages
// reach storage through its methods; the handle never escapes.
type Store struct {
	db *sql.DB
}

