// Open opens the SQLite database at dsn (WAL journal mode, 5s busy_timeout),
// runs the idempotent schema migrations, and returns a *Store — safe on an
// existing database (every statement is CREATE ... IF NOT EXISTS).
func Open(ctx context.Context, dsn string) (*Store, error) {
	db, err := sql.Open(sqliteDriver, withBusyTimeout(dsn))
	if err != nil {
		return nil, fmt.Errorf("store: open %q: %w", dsn, err)
	}
	if _, err := db.ExecContext(ctx, "PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("store: set WAL: %w", err)
	}
	for _, stmt := range schemaSQL {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			db.Close()
			return nil, fmt.Errorf("store: migrate: %w", err)
		}
	}
	// The one-time guarded device_tokens → credentials copy (accounts 2.2/D6)
	// runs after the DDL has ensured both tables exist; idempotent across
	// boots (the guard is the token_hash itself).
	if err := migrateDeviceTokens(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureItemsStatus(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureLibrariesDescription(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureLibrariesStreamsEnabled(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureLibrariesNamingGroupStyle(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureLibrariesNamingElementName(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensurePlaybackProgressSeconds(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	if err := ensureCredentialsDebug(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	// The one-time guarded ledger rebuild (accounts 2.3 — see
	// migrateLedgersUserScoped) runs LAST: its copy names position_seconds,
	// the column ensurePlaybackProgressSeconds has just ALTERed in on
	// pre-phase-3 databases.
	if err := migrateLedgersUserScoped(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	return &Store{db: db}, nil
}

// busyTimeoutPragma is the per-write-lock wait budget (milliseconds): 5s — the
// §4.4 soft bound, long enough to ride out a neighboring write, short enough
// never to stall a request past the §7.6 RPC timeout window.
const busyTimeoutPragma = 5000

// withBusyTimeout appends the busy_timeout PRAGMA to the DSN as a modernc
// _pragma query parameter. busy_timeout is a PER-CONNECTION setting (unlike
// persistent WAL), and database/sql pools connections — the DSN is the only
// way every pooled connection inherits it (modernc's default is 0), making it
// the root-cause fix for the async substrate's concurrent-write lock errors
// (the queue's writeMu serializes only its own writes; scan PutItem + the API
// are independent writers).
func withBusyTimeout(dsn string) string {
	sep := "?"
	if strings.Contains(dsn, "?") {
		sep = "&"
	}
	return fmt.Sprintf("%s%s_pragma=busy_timeout(%d)", dsn, sep, busyTimeoutPragma)
}

// ensureColumn is the shared guarded-ALTER primitive for columns added after a
// table first shipped, and the CANONICAL home of the additive-migration
// mechanics its ensure* wrappers point to. SQLite has no ADD COLUMN IF NOT
// EXISTS, so Open probes PRAGMA table_info and ALTERs only when the column is
// absent — the guard is what keeps re-running Open safe
// (INV-idempotent-migration); fresh DBs already get the column from the
// CREATE TABLE in schemaSQL, pre-existing DBs get it here. addDDL must be
// the static ALTER statement matching the column declared in schemaSQL
// (identifiers are constants, never data — INV1).
func ensureColumn(ctx context.Context, db *sql.DB, table, column, addDDL string) error {
	rows, err := db.QueryContext(ctx, "PRAGMA table_info("+table+")")
	if err != nil {
		return fmt.Errorf("store: migrate %s.%s (table_info): %w", table, column, err)
	}
	hasColumn := false
	for rows.Next() {
		var (
			cid     int
			name    string
			ctype   string
			notnull int
			dflt    sql.NullString
			pk      int
		)
		if err := rows.Scan(&cid, &name, &ctype, &notnull, &dflt, &pk); err != nil {
			rows.Close()
			return fmt.Errorf("store: migrate %s.%s (scan): %w", table, column, err)
		}
		if name == column {
			hasColumn = true
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("store: migrate %s.%s (rows): %w", table, column, err)
	}
	if !hasColumn {
		if _, err := db.ExecContext(ctx, addDDL); err != nil {
			return fmt.Errorf("store: migrate %s.%s (alter): %w", table, column, err)
		}
	}
	return nil
}

// ensureItemsStatus makes Open additive across scan-library databases: the
// items.status column + its index (additive mechanics — see ensureColumn),
// the index created AFTER the column so fresh and migrated DBs both end
// indexed. Value-agnostic store (ERROR-FLOOR LAW, doc.go # Invariants): the
// lifecycle set lives in internal/enrich.
func ensureItemsStatus(ctx context.Context, db *sql.DB) error {
	if err := ensureColumn(ctx, db, "items", "status",
		"ALTER TABLE items ADD COLUMN status TEXT NOT NULL DEFAULT 'new'"); err != nil {
		return err
	}
	if _, err := db.ExecContext(ctx,
		"CREATE INDEX IF NOT EXISTS items_status ON items(status)"); err != nil {
		return fmt.Errorf("store: migrate items_status index: %w", err)
	}
	return nil
}

