func ensureLibrariesDescription(ctx context.Context, db *sql.DB) error {
	return ensureColumn(ctx, db, "libraries", "description",
		"ALTER TABLE libraries ADD COLUMN description TEXT NOT NULL DEFAULT ''")
}

